"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[17989],{38887(e,a,r){r.r(a),r.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>n,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/docker/modulos/registry-harbor-artefactos/cuestionario","title":"Cuestionario M20 \u2014 Registry, Harbor y Gesti\xf3n de Artefactos","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/20-registry-harbor-artefactos/cuestionario.md","sourceDirName":"cursos/docker/modulos/20-registry-harbor-artefactos","slug":"/cursos/docker/modulos/registry-harbor-artefactos/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/registry-harbor-artefactos/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/registry-harbor-artefactos/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/registry-harbor-artefactos/ejercicio"}}');var o=r(74848),i=r(28453);const n={sidebar_label:"Cuestionario"},t="Cuestionario M20 \u2014 Registry, Harbor y Gesti\xf3n de Artefactos",c={},l=[{value:"1. [Investigar] \xbfQu\xe9 es exactamente la OCI Distribution Spec v1.1 y qu\xe9 nuevas capacidades introduce respecto a v1.0? \xbfC\xf3mo habilita el ecosistema de supply chain (firmas, SBOMs)?",id:"1-investigar-qu\xe9-es-exactamente-la-oci-distribution-spec-v11-y-qu\xe9-nuevas-capacidades-introduce-respecto-a-v10-c\xf3mo-habilita-el-ecosistema-de-supply-chain-firmas-sboms",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente ORAS (OCI Registry As Storage) y c\xf3mo permite almacenar cualquier tipo de artefacto en un registry OCI? \xbfQu\xe9 artefactos m\xe1s all\xe1 de im\xe1genes son posibles?",id:"2-investigar-qu\xe9-es-exactamente-oras-oci-registry-as-storage-y-c\xf3mo-permite-almacenar-cualquier-tipo-de-artefacto-en-un-registry-oci-qu\xe9-artefactos-m\xe1s-all\xe1-de-im\xe1genes-son-posibles",level:3},{value:"3. [Investigar] \xbfQu\xe9 arquitectura de alta disponibilidad soporta Harbor? \xbfC\xf3mo se scalea horizontalmente y qu\xe9 componentes son stateful vs stateless?",id:"3-investigar-qu\xe9-arquitectura-de-alta-disponibilidad-soporta-harbor-c\xf3mo-se-scalea-horizontalmente-y-qu\xe9-componentes-son-stateful-vs-stateless",level:3},{value:"4. [Investigar] \xbfQu\xe9 son exactamente los &quot;SBOMs&quot; y c\xf3mo se integran en Harbor? \xbfQu\xe9 formatos soporta (SPDX vs CycloneDX) y c\xf3mo se adjuntan a las im\xe1genes?",id:"4-investigar-qu\xe9-son-exactamente-los-sboms-y-c\xf3mo-se-integran-en-harbor-qu\xe9-formatos-soporta-spdx-vs-cyclonedx-y-c\xf3mo-se-adjuntan-a-las-im\xe1genes",level:3},{value:"5. [Conectar] La clase menciona Cosign. \xbfC\xf3mo funciona exactamente el &quot;keyless signing&quot; con Cosign y Sigstore? \xbfQu\xe9 es Rekor y qu\xe9 valor agrega al proceso de firma?",id:"5-conectar-la-clase-menciona-cosign-c\xf3mo-funciona-exactamente-el-keyless-signing-con-cosign-y-sigstore-qu\xe9-es-rekor-y-qu\xe9-valor-agrega-al-proceso-de-firma",level:3},{value:"6. [Conectar] \xbfC\xf3mo funciona exactamente la replicaci\xf3n de im\xe1genes en Harbor? \xbfQu\xe9 diferencia hay entre replicaci\xf3n push-based y pull-based?",id:"6-conectar-c\xf3mo-funciona-exactamente-la-replicaci\xf3n-de-im\xe1genes-en-harbor-qu\xe9-diferencia-hay-entre-replicaci\xf3n-push-based-y-pull-based",level:3},{value:"7. [Conectar] \xbfQu\xe9 pol\xedticas de retenci\xf3n y garbage collection tienen Harbor y c\xf3mo se diferencian? \xbfPor qu\xe9 GC debe ejecutarse fuera de horario pico?",id:"7-conectar-qu\xe9-pol\xedticas-de-retenci\xf3n-y-garbage-collection-tienen-harbor-y-c\xf3mo-se-diferencian-por-qu\xe9-gc-debe-ejecutarse-fuera-de-horario-pico",level:3},{value:"8. [Cuestionar] \xbfEs Harbor el registry enterprise definitivo o hay alternativas (Quay, Nexus, Artifactory) que son mejores para ciertos casos?",id:"8-cuestionar-es-harbor-el-registry-enterprise-definitivo-o-hay-alternativas-quay-nexus-artifactory-que-son-mejores-para-ciertos-casos",level:3},{value:"9. [Cuestionar] \xbfDeber\xedas usar un registry privado auto-gestionado (Harbor) o un registry cloud gestionado (ECR, ACR, GAR)? \xbfCu\xe1les son los trade-offs reales?",id:"9-cuestionar-deber\xedas-usar-un-registry-privado-auto-gestionado-harbor-o-un-registry-cloud-gestionado-ecr-acr-gar-cu\xe1les-son-los-trade-offs-reales",level:3},{value:"10. [Cuestionar] \xbfSon las &quot;robot accounts&quot; de Harbor una buena pr\xe1ctica o deber\xedan reemplazarse con OIDC workload identity en CI/CD?",id:"10-cuestionar-son-las-robot-accounts-de-harbor-una-buena-pr\xe1ctica-o-deber\xedan-reemplazarse-con-oidc-workload-identity-en-cicd",level:3}];function d(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.header,{children:(0,o.jsx)(a.h1,{id:"cuestionario-m20--registry-harbor-y-gesti\xf3n-de-artefactos",children:"Cuestionario M20 \u2014 Registry, Harbor y Gesti\xf3n de Artefactos"})}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,o.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"1-investigar-qu\xe9-es-exactamente-la-oci-distribution-spec-v11-y-qu\xe9-nuevas-capacidades-introduce-respecto-a-v10-c\xf3mo-habilita-el-ecosistema-de-supply-chain-firmas-sboms",children:"1. [Investigar] \xbfQu\xe9 es exactamente la OCI Distribution Spec v1.1 y qu\xe9 nuevas capacidades introduce respecto a v1.0? \xbfC\xf3mo habilita el ecosistema de supply chain (firmas, SBOMs)?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": OCI Distribution Spec v1.1 (abril 2024) agrega: 1) ",(0,o.jsx)(a.strong,{children:"Referrers API"}),": permite listar artefactos relacionados con una imagen (firmas, SBOMs, attestations) sin tags hack. Antes, Cosign usaba tags ",(0,o.jsx)(a.code,{children:".sig"})," y ",(0,o.jsx)(a.code,{children:".sbom"})," (workaround). Ahora ",(0,o.jsx)(a.code,{children:"GET /v2/&#x3C;name>/referrers/&#x3C;digest>"})," devuelve la lista de artefactos asociados. 2) ",(0,o.jsx)(a.strong,{children:"ArtifactType en manifest"}),": permite diferenciar tipos de artefactos (imagen vs chart Helm vs WASM module) sin depender de config.mediaType. 3) ",(0,o.jsx)(a.strong,{children:"subject field"}),": un artifact puede declarar a qu\xe9 otro manifiesto hace referencia (ej. una firma declara ",(0,o.jsx)(a.code,{children:"subject: &#x3C;digest-de-la-imagen>"}),"). Esto estandariza c\xf3mo adjuntar metadatos a im\xe1genes en cualquier registry OCI-compliant. Cosign, Notation, y ORAS est\xe1n migrando a usar referrers API en lugar de tags."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La spec v1.1 fue liderada por Steve Lasker (Microsoft, chair del OCI Technical Oversight Committee) y el equipo de distribuci\xf3n OCI. El problema que resuelve: antes de v1.1, no hab\xeda forma est\xe1ndar de relacionar artefactos. Cosign creaba un tag ",(0,o.jsx)(a.code,{children:".sig"}),", Syft sub\xeda un SBOM como imagen separada, y el discovery de estos artefactos era fr\xe1gil (parsing de tags). Referrers API + subject field estandarizan esto. Harbor 2.10+, ECR, ACR, y registry:2 ya soportan v1.1 parcial o totalmente."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-oras-oci-registry-as-storage-y-c\xf3mo-permite-almacenar-cualquier-tipo-de-artefacto-en-un-registry-oci-qu\xe9-artefactos-m\xe1s-all\xe1-de-im\xe1genes-son-posibles",children:"2. [Investigar] \xbfQu\xe9 es exactamente ORAS (OCI Registry As Storage) y c\xf3mo permite almacenar cualquier tipo de artefacto en un registry OCI? \xbfQu\xe9 artefactos m\xe1s all\xe1 de im\xe1genes son posibles?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": ORAS (oras.land, proyecto CNCF Sandbox) es una librer\xeda y CLI que permite hacer push/pull de cualquier tipo de archivo a un registry OCI usando la OCI Distribution Spec. Trata al registry como un almacenamiento gen\xe9rico de artefactos, no solo contenedores. Posibles artefactos: 1) Helm charts (",(0,o.jsx)(a.code,{children:"helm push oci://..."})," usa ORAS), 2) WebAssembly modules, 3) CNAB bundles (paquetes de aplicaciones cloud), 4) OPA policies (Rego files), 5) SBOMs (SPDX/CycloneDX), 6) Firmas (Cosign), 7) Archivos de configuraci\xf3n arbitrarios (YAML, JSON). ORAS organiza artefactos en layers (como capas de imagen) y manifiestos. El CLI ",(0,o.jsx)(a.code,{children:"oras push"})," sube archivos al registry, ",(0,o.jsx)(a.code,{children:"oras pull"})," los descarga. Harbor integra ORAS nativamente (soporta cualquier artifact type)."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': ORAS fue creado por Steve Lasker (Microsoft) y Josh Dolitsky (Blood Orange) como parte del movimiento de "registries como almacenamiento universal cloud-native". La idea: en lugar de tener Nexus (JARs), Artifactory (de todo), y Docker Registry (im\xe1genes), todo puede ir a un registry OCI. Helm 3.8+ usa ORAS para charts OCI. Cosign usa ORAS para subir firmas. Notation usa ORAS para subir signatures. El CLI oras es la herramienta universal de interacci\xf3n con registries OCI m\xe1s all\xe1 de Docker.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"3-investigar-qu\xe9-arquitectura-de-alta-disponibilidad-soporta-harbor-c\xf3mo-se-scalea-horizontalmente-y-qu\xe9-componentes-son-stateful-vs-stateless",children:"3. [Investigar] \xbfQu\xe9 arquitectura de alta disponibilidad soporta Harbor? \xbfC\xf3mo se scalea horizontalmente y qu\xe9 componentes son stateful vs stateless?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Harbor es un conjunto de microservicios, cada uno con diferentes requisitos de HA: 1) ",(0,o.jsx)(a.strong,{children:"Stateless"})," (escalan horizontalmente sin problema): Harbor Core (API/UI), Trivy (escaneo), Jobservice (limpieza, replicaci\xf3n), Registry (distribution/distribution). Pueden correr m\xfaltiples r\xe9plicas detr\xe1s de un load balancer. 2) ",(0,o.jsx)(a.strong,{children:"Stateful"})," (requieren almacenamiento persistente y HA espec\xedfica): PostgreSQL (metadata del registry, usuarios, proyectos, pol\xedticas) \u2014 requiere HA con streaming replication (o usar RDS externo), Redis (cache, sesiones, job queue) \u2014 requiere HA con Sentinel o Cluster, Storage backend (im\xe1genes) \u2014 debe ser compartido (S3, NFS, almacenamiento en bloque con ReadWriteOnce). Harbor recomienda externalizar PostgreSQL y Redis (usar servicios gestionados) y usar S3-compatible storage para el registry. En K8s, Harbor se despliega via Helm chart oficial con soporte para HA (m\xfaltiples r\xe9plicas de componentes stateless, PVCs para stateful)."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de Harbor (goharbor.io) detalla la arquitectura de HA. En producci\xf3n, la configuraci\xf3n recomendada es: 1) Harbor desplegado en K8s con el Helm chart oficial, 2) PostgreSQL externo (AWS RDS, Cloud SQL) con HA, 3) Redis externo (ElastiCache, Memorystore) con HA, 4) Storage: S3 (o GCS, Azure Blob) para im\xe1genes (usando el driver S3 del registry). Esto permite que los Pods de Harbor sean ef\xedmeros y escalen horizontalmente."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"4-investigar-qu\xe9-son-exactamente-los-sboms-y-c\xf3mo-se-integran-en-harbor-qu\xe9-formatos-soporta-spdx-vs-cyclonedx-y-c\xf3mo-se-adjuntan-a-las-im\xe1genes",children:'4. [Investigar] \xbfQu\xe9 son exactamente los "SBOMs" y c\xf3mo se integran en Harbor? \xbfQu\xe9 formatos soporta (SPDX vs CycloneDX) y c\xf3mo se adjuntan a las im\xe1genes?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": SBOM (Software Bill of Materials) es un inventario de todos los componentes, bibliotecas, y versiones en una imagen. Harbor soporta SBOMs desde la versi\xf3n 2.10: 1) Generaci\xf3n autom\xe1tica: cuando se escanea una imagen con Trivy (scanner integrado), Trivy genera un SBOM autom\xe1ticamente (lista de paquetes del SO y dependencias de aplicaci\xf3n). 2) Adjunto: el SBOM se sube al registry como artifact OCI relacionado (usando referrers API o subject field), adjunto a la imagen. 3) Visualizaci\xf3n: en la UI de Harbor, cada imagen muestra su SBOM (lista de componentes y versiones). 4) Formatos: Harbor soporta SPDX (Linux Foundation) y CycloneDX (OWASP). Ambos son est\xe1ndares abiertos para SBOM. La diferencia: SPDX es m\xe1s orientado a licencias y compliance, CycloneDX a seguridad. Trivy genera ambos formatos."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": El soporte de SBOMs en Harbor fue impulsado por la orden ejecutiva 14028 de la Casa Blanca (2021) y la creciente demanda de compliance. La integraci\xf3n con Trivy hace que sea autom\xe1tico: cada imagen escaneada tiene su SBOM disponible. Para exportar: ",(0,o.jsx)(a.code,{children:"oras pull harbor.local/project/image:tag --sbom"})," (o via API). La trazabilidad: saber que la imagen usa log4j 2.17.1 en lugar de 2.14.0 que tiene CVE. Para compliance FedRAMP/PCI/HIPAA, SBOMs son cada vez m\xe1s requeridos."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-cosign-c\xf3mo-funciona-exactamente-el-keyless-signing-con-cosign-y-sigstore-qu\xe9-es-rekor-y-qu\xe9-valor-agrega-al-proceso-de-firma",children:'5. [Conectar] La clase menciona Cosign. \xbfC\xf3mo funciona exactamente el "keyless signing" con Cosign y Sigstore? \xbfQu\xe9 es Rekor y qu\xe9 valor agrega al proceso de firma?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Keyless signing con Cosign (Sigstore): 1) No gener\xe1s ni manejas claves privadas locales. 2) Cosign inicia un flujo OIDC (OpenID Connect) con tu proveedor de identidad (Google, GitHub, Microsoft). 3) El proveedor emite un ID token JWT que prueba tu identidad (ej. tu direcci\xf3n de email en GitHub). 4) Cosign usa el token para solicitar un certificado ef\xedmero X.509 de Fulcio (CA de Sigstore, emitida por la Linux Foundation). 5) Cosign firma la imagen con este certificado (que es v\xe1lido solo por 10 minutos). 6) Cosign registra la firma en Rekor (transparency log p\xfablico e inmutable). El resultado: cualquiera puede verificar que la imagen fue firmada por tu identidad, sin tener tu clave p\xfablica (la verificaci\xf3n usa el certificado y verifica el registro en Rekor). Rekor agrega "non-repudiation": la firma es p\xfablicamente auditable (timestamped, inmutable). No pod\xe9s negar haber firmado.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": Sigstore fue creado por Luke Hinds (Red Hat), Dan Lorenc (Google/Chainguard), y la comunidad. Rekor (transparency log) es la innovaci\xf3n clave: es un Merkle tree p\xfablico donde cada entrada es inmutable. Si alguien compromete tu identidad OIDC, la firma fraudulenta queda registrada en Rekor p\xfablicamente y es detectable. Esto es superior a GPG/PGP (donde las claves no tienen transparencia). Cosign keyless es el futuro de la firma de im\xe1genes: sin gesti\xf3n de claves, con auditabilidad p\xfablica."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"6-conectar-c\xf3mo-funciona-exactamente-la-replicaci\xf3n-de-im\xe1genes-en-harbor-qu\xe9-diferencia-hay-entre-replicaci\xf3n-push-based-y-pull-based",children:"6. [Conectar] \xbfC\xf3mo funciona exactamente la replicaci\xf3n de im\xe1genes en Harbor? \xbfQu\xe9 diferencia hay entre replicaci\xf3n push-based y pull-based?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Replicaci\xf3n push-based: Harbor ORIGEN inicia la transferencia. La instancia de Harbor (origen) se conecta al registry destino y empuja las im\xe1genes. \xdatil cuando el destino no tiene acceso de red al origen (firewall). Replicaci\xf3n pull-based: Harbor DESTINO inicia la transferencia. La instancia de Harbor (destino) se conecta al registry origen y jala las im\xe1genes. \xdatil para cumplir pol\xedticas de firewall (solo se permite tr\xe1fico saliente desde el destino). La replicaci\xf3n se configura por proyecto con filtros (nombre de imagen, tag, label) y triggers (manual, schedule, o event-based: cada push dispara replicaci\xf3n). Modos: Full (replica todo), Selective (por filtros). La replicaci\xf3n es a nivel de blob (las capas compartidas se copian una vez, no duplican). Soporta destinos: otro Harbor, Docker Hub, ECR, GCR, ACR, registry OCI."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": La replicaci\xf3n de Harbor usa el mismo mecanismo de distribuci\xf3n OCI (push/pull de blobs y manifiestos). Para redes air-gapped, Harbor puede exportar im\xe1genes como tar para sneakernet (USB) y la replicaci\xf3n pull-based desde el destino las importa. La replicaci\xf3n event-based es \xfatil para CI/CD: tan pronto como una imagen se sube a Harbor-dev, se replica autom\xe1ticamente a Harbor-staging."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"7-conectar-qu\xe9-pol\xedticas-de-retenci\xf3n-y-garbage-collection-tienen-harbor-y-c\xf3mo-se-diferencian-por-qu\xe9-gc-debe-ejecutarse-fuera-de-horario-pico",children:"7. [Conectar] \xbfQu\xe9 pol\xedticas de retenci\xf3n y garbage collection tienen Harbor y c\xf3mo se diferencian? \xbfPor qu\xe9 GC debe ejecutarse fuera de horario pico?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),': Pol\xedticas de retenci\xf3n: reglas declarativas por proyecto que definen qu\xe9 tags/im\xe1genes eliminar autom\xe1ticamente (ej. mantener \xfaltimas 10 versiones, eliminar im\xe1genes sin tag despu\xe9s de 24h). La retenci\xf3n solo MARCA manifiestos para eliminaci\xf3n (los "desreferencia"). Garbage Collection (GC): proceso que recorre los blobs en storage y elimina los que ya no son referenciados por ning\xfan manifest. GC debe ejecutarse fuera de horario pico porque: 1) en versiones de Harbor <2.0, GC pon\xeda el registry en modo read-only (pulls funcionan, pushes no), 2) GC consume I/O del storage (lee metadatos de todos los blobs), 3) en storage compartido (S3), GC puede generar tr\xe1fico significativo. Harbor 2.0+ implementa "online GC" que no bloquea pushes, pero sigue consumiendo I/O.']}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': La documentaci\xf3n de Harbor (GC) recomienda ejecutar GC semanalmente en ventanas de bajo uso. La retenci\xf3n se ejecuta m\xe1s frecuentemente (diario) porque solo modifica metadata (manifests) sin tocar blobs. El GC es necesario porque cuando un manifest se elimina (por retenci\xf3n o manualmente), los blobs no se eliminan autom\xe1ticamente (pueden ser compartidos). Sin GC, el storage crece indefinidamente. Harbor tambi\xe9n tiene "blob replication" (replicaci\xf3n a nivel de blob, no de manifiesto) para optimizar la sincronizaci\xf3n.']}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"8-cuestionar-es-harbor-el-registry-enterprise-definitivo-o-hay-alternativas-quay-nexus-artifactory-que-son-mejores-para-ciertos-casos",children:"8. [Cuestionar] \xbfEs Harbor el registry enterprise definitivo o hay alternativas (Quay, Nexus, Artifactory) que son mejores para ciertos casos?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Harbor domina para contenedores y OCI artifacts. Alternativas: 1) ",(0,o.jsx)(a.strong,{children:"Quay"})," (Red Hat): m\xe1s ligero que Harbor, enfocado en im\xe1genes OCI, con escaneo integrado (Clair) y firma (Cosign). Mejor si ya est\xe1s en el ecosistema Red Hat/OpenShift. 2) ",(0,o.jsx)(a.strong,{children:"Nexus Repository"})," (Sonatype): repositorio universal (Maven, npm, PyPI, Docker, Helm, etc.) con un solo producto. Mejor si necesit\xe1s un \xdaNICO repositorio para m\xfaltiples tipos de artefactos (no solo containers). 3) ",(0,o.jsx)(a.strong,{children:"Artifactory"})," (JFrog): similar a Nexus, repositorio universal muy maduro, con build integration avanzada y CI/CD pipeline tracing. Mejor para empresas grandes con m\xfaltiples tipos de artefactos y compliance avanzado. Harbor es el mejor para ecosistema cloud-native (OCI, Helm, Cosign, SBOMs) y solo contenedores. Para empresas con Java + npm + Docker + NuGet, Nexus/Artifactory evitan tener m\xfaltiples registries."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": El landscape de artefactos cloud-native muestra una bifurcaci\xf3n: registries especializados en OCI (Harbor, Quay) vs registries universales (Nexus, Artifactory). Harbor es CNCF graduated, open-source, y con features enterprise gratuitas (Quay idem). Nexus y Artifactory son productos comerciales (con ediciones open-source limitadas). Para la mayor\xeda de los equipos cloud-native modernos, Harbor es la mejor opci\xf3n por features y costo."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"9-cuestionar-deber\xedas-usar-un-registry-privado-auto-gestionado-harbor-o-un-registry-cloud-gestionado-ecr-acr-gar-cu\xe1les-son-los-trade-offs-reales",children:"9. [Cuestionar] \xbfDeber\xedas usar un registry privado auto-gestionado (Harbor) o un registry cloud gestionado (ECR, ACR, GAR)? \xbfCu\xe1les son los trade-offs reales?"}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Cloud gestionado (ECR/ACR/GAR): cero operaciones (no gestion\xe1s storage, HA, parches), integraci\xf3n IAM nativa (sin credenciales, usa roles), escalabilidad infinita (sin GC manual), replicaci\xf3n multi-regi\xf3n autom\xe1tica (si us\xe1s el servicio del cloud provider). Auto-gestionado (Harbor): control total sobre los datos (air-gapped, compliance de ubicaci\xf3n), features avanzadas (firma, escaneo, proxy cache, retenci\xf3n detallada) que el cloud puede no ofrecer en el mismo nivel, costo predecible (sin sorpresas de transferencia de datos). El trade-off: \xbfprefer\xeds no gestionar infraestructura (cloud) o necesit\xe1s features/control que solo Harbor da? Para la mayor\xeda: registry cloud para simplicidad, Harbor para casos espec\xedficos (air-gapped, multi-cloud, features avanzadas de seguridad)."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),": Los registries cloud han mejorado mucho: ECR tiene scanning (Inspector), replication (cross-account/region), y lifecycle policies. GAR tiene vulnerability scanning y metadata storage. Pero Harbor ofrece m\xe1s granularidad (pol\xedticas de retenci\xf3n por tag, RBAC por proyecto, proxy cache integrado, soporte Cosign/Notation UI). La decisi\xf3n tambi\xe9n es econ\xf3mica: el storage es barato (~$0.10/GB/mes), pero la transferencia de datos puede ser cara (egress a internet). Harbor on-prem elimina costos de transferencia para pulls internos."]}),"\n",(0,o.jsx)(a.hr,{}),"\n",(0,o.jsx)(a.h3,{id:"10-cuestionar-son-las-robot-accounts-de-harbor-una-buena-pr\xe1ctica-o-deber\xedan-reemplazarse-con-oidc-workload-identity-en-cicd",children:'10. [Cuestionar] \xbfSon las "robot accounts" de Harbor una buena pr\xe1ctica o deber\xedan reemplazarse con OIDC workload identity en CI/CD?'}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Respuesta"}),": Robot accounts son una buena pr\xe1ctica para CI/CD simple y equipos que no tienen OIDC workload identity configurado. Ventajas: f\xe1ciles de crear, permisos granulares, tokens con expiraci\xf3n, audit trail (sab\xe9s qu\xe9 robot hizo qu\xe9). Desventajas: los tokens son secretos est\xe1ticos (deben rotarse, pueden filtrarse). OIDC workload identity (ej. GitHub Actions OIDC \u2192 Harbor OIDC) es m\xe1s seguro: no hay secretos est\xe1ticos, la autenticaci\xf3n es temporal (token ef\xedmero), y la identidad del pipeline es verificable criptogr\xe1ficamente (sin secretos compartidos). La tendencia es migrar a OIDC para CI/CD, manteniendo robot accounts solo para casos donde OIDC no es posible (sistemas legacy, scripts manuales). Harbor soporta OIDC (desde v2.5) para autenticaci\xf3n de usuarios y puede extenderse a CI/CD via exchange token."]}),"\n",(0,o.jsxs)(a.p,{children:[(0,o.jsx)(a.strong,{children:"Por qu\xe9"}),': GitHub Actions permite OIDC tokens (Actions \u2192 Harbor) desde 2021. GitLab CI idem. Esto elimina el "secret zero" problem (\xbfd\xf3nde almaceno el token de Harbor para CI?). Con OIDC, el CI presenta un token JWT firmado por GitHub/GitLab al Harbor, Harbor lo verifica, y emite un token de acceso temporal. La seguridad mejora dr\xe1sticamente (sin secretos est\xe1ticos que rotar). Robot accounts seguir\xe1n existiendo para casos de uso simples.']})]})}function u(e={}){const{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,a,r){r.d(a,{R:()=>n,x:()=>t});var s=r(96540);const o={},i=s.createContext(o);function n(e){const a=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:n(e.components),s.createElement(i.Provider,{value:a},e.children)}}}]);